#!/usr/bin/env python3
"""Profile an actual dishwashing result with the optional C block sampler."""
import os,json,pathlib,sys,time,urllib.request,concurrent.futures,subprocess
prefix=sys.argv[1];base=json.loads(pathlib.Path(os.environ.get('OU_CONTROL_RECORD','analysis/performance-profile-control.json')).read_text())['control_url']
def req(action,**kw):
 with urllib.request.urlopen(urllib.request.Request(base,data=json.dumps(dict(action=action,**kw)).encode(),headers={'Content-Type':'application/json'}),timeout=650)as response:return json.load(response).get('result')
wait='''(async()=>{const o=orderup,r=o.runtime,m=r.u32(r.elf.address('_ZN15CleanupMinigame9g_ManagerE'));await o.controller.resume();const start=performance.now();while(r.u32(m+0x58)<2&&performance.now()-start<90000&&!o.error)await new Promise(resolve=>setTimeout(resolve,40));await o.controller.pause();return{phase:r.u32(m+0x58),cleaned:r.u32(m+0x60),error:o.error};})()'''
with concurrent.futures.ThreadPoolExecutor()as pool:
 future=pool.submit(req,'eval',source=wait);time.sleep(.5);req('label',text='OK',options={'after':100});subprocess.run(['python3','tools/perf_cleanup_mouse.py',prefix+'-mouse.json'],check=True);ready=future.result()
assert ready['phase']==2,ready;print({'ready':ready},flush=True)
source='''(async()=>{const o=orderup,r=o.runtime,uc=r.uc,m=r.u32(r.elf.address('_ZN15CleanupMinigame9g_ManagerE')),handle=uc.getValue(r.engine.handle_ptr,'*'),profile=uc._ou_profile_create(handle,0,0x470000,67);if(!profile)throw Error('Native profiler unavailable');const invalidate=()=>uc.ccall('uc_ctl','number',['pointer','number','pointer'],[handle,0x4000000a,0]);let seen=0,fast_frames=0,previous=r.nativeHot.report(),slow=new Map(),fast=new Map();const slow_frames=[],frames=[];r.nativeHot.gcTimings(true);o.timings.push=function(work){const used=uc._ou_profile_count(profile,0),p=uc._ou_profile_data(profile),rows=new Uint32Array(uc.HEAPU8.buffer,p,used*3),ports=r.nativeHot.report(),delta=Object.fromEntries(Object.entries(ports).filter(([k,v])=>typeof v==='number').map(([k,v])=>[k,v-previous[k]]));previous=ports;const detail={frame:o.frames,phase:r.u32(m+0x58),work,blocks:uc._ou_profile_count(profile,1),samples:uc._ou_profile_count(profile,2),dropped:uc._ou_profile_count(profile,3),ports:delta};if(++seen>6){frames.push(detail);const target=work>50?slow:fast;for(let i=0;i<rows.length;i+=3)target.set(rows[i],(target.get(rows[i])||0)+rows[i+1]);if(work>50)slow_frames.push({...detail,gc:r.nativeHot.gcTimings(),imports:r.recentCalls.slice(-10)});else fast_frames++;}uc._ou_profile_clear(profile);return Array.prototype.push.call(this,work);};try{invalidate();uc._ou_profile_enable(profile,1);await o.controller.resume();const start=performance.now();while(r.u32(m+0x58)!==3&&performance.now()-start<30000&&!o.error)await new Promise(resolve=>setTimeout(resolve,100));await new Promise(resolve=>setTimeout(resolve,1800));await o.controller.pause();return{diagnostic_not_fps:true,native_c_sampler:true,frames,slow_frames,fast_frames,slow:[...slow],fast:[...fast],phase:r.u32(m+0x58),error:o.error};}finally{await o.controller.pause();delete o.timings.push;uc._ou_profile_enable(profile,0);uc._ou_profile_destroy(profile);invalidate();}})()'''
req('profile-start')
try:result=req('eval',source=source)
finally:req('profile-stop',path=prefix+'.cpuprofile')
pathlib.Path(prefix+'.json').write_text(json.dumps(result));req('screen',path=prefix+'-result.png');print({'slow_frames':[(x['frame'],x['phase'],x['work'])for x in result['slow_frames']],'fast_frames':result['fast_frames'],'phase':result['phase'],'error':result['error']},flush=True)
